function REDUCE_STEP(p):
  // Distributive rules
  if p = cut(tmin(a, b), r):
    return tmin(cut(a, r), cut(b, r))
  if p = cut(r, tmin(a, b)):
    return tmin(cut(r, a), cut(r, b))
  // Idempotent collapse
  if p = tmin(q, q):
    return q
  // Computation rules
  if p = cut(atom(a), atom(b)):
    return atom(a + b)
  // Congruence: reduce subterms
  ...

function NORMALIZE_BY_REDUCTION(p):
  while REDUCE_STEP(p) ≠ None:
    p ← REDUCE_STEP(p)
  return p

